package com.autocare.platform.order;
import com.autocare.platform.gateway.identity.*;
import com.autocare.platform.vehicle.VehicleOwner;
import com.autocare.platform.common.write.WriteIntegrityService.*;
import com.fasterxml.jackson.databind.JsonNode;
import java.util.*;
import static com.autocare.platform.order.ReservationStore.*;

/** Owner-submitted text and explicit operator assignment; no implicit archive access. */
public class DiagnosisCases {
 final ReservationStore db;final DiagnosisServicePolicies service;final InviteDiagnosisPolicies eligibility;
 public DiagnosisCases(ReservationStore db,DiagnosisServicePolicies service,InviteDiagnosisPolicies eligibility){this.db=db;this.service=service;this.eligibility=eligibility;}
 static JsonNode input(String raw,String action){var b=CouponInput.parse(raw);switch(action){
  case "create"->{CouponInput.exact(b,"vehicle_id","policy_id","policy_revision","message","consent");CouponInput.id(b.get("vehicle_id"));admissionInput(b);}
  case "message"->{CouponInput.exact(b,"expected_revision","policy_id","policy_revision","message","consent");CouponInput.version(b.get("expected_revision"));admissionInput(b);}
  case "reply"->{CouponInput.exact(b,"expected_revision","message");CouponInput.version(b.get("expected_revision"));messageText(b.get("message"));}
  case "assign"->{CouponInput.exact(b,"expected_revision","operator_id");CouponInput.version(b.get("expected_revision"));CouponInput.id(b.get("operator_id"));}
  case "close"->{CouponInput.exact(b,"expected_revision");CouponInput.version(b.get("expected_revision"));}
  default->throw ReservationInput.bad();}return b;
 }
 static String messageText(JsonNode n){if(n==null||!n.isTextual())throw ReservationInput.bad();String value=n.textValue();DiagnosisServicePolicies.text(com.fasterxml.jackson.databind.node.TextNode.valueOf(value.replace("\n"," ")),1,2000);return value;}
 private static void admissionInput(JsonNode b){CouponInput.id(b.get("policy_id"));CouponInput.id(b.get("policy_revision"));messageText(b.get("message"));if(!b.path("consent").isBoolean()||!b.path("consent").asBoolean())throw ReservationInput.bad();}
 Map<String,Object> row(long id,boolean lock){return db.one("SELECT * FROM diagnosis_case WHERE id=?"+(lock?" FOR UPDATE":""),id);}
 private Map<String,Object> owner(VehicleOwner a,long id,boolean lock){db.owner(a,lock);return db.one("SELECT * FROM diagnosis_case WHERE id=? AND owner_id=?"+(lock?" FOR UPDATE":""),id,a.id());}
 private void handler(OperatorActor a,Map<String,Object> c,boolean lock){service.operators.authorize(a,OperatorIdentity.Permission.DIAGNOSE,lock);if(c.get("assigned_operator_id")==null||number(c,"assigned_operator_id")!=a.id())throw missing();}
 private void scope(Object a,long id,boolean lock,boolean closing){if(a instanceof VehicleOwner u){owner(u,id,lock);return;}var op=(OperatorActor)a;service.operators.authorize(op,OperatorIdentity.Permission.NONE,lock);var c=row(id,lock);if(closing&&db.jdbc.queryForObject("SELECT can_diagnose_manage FROM operator_account WHERE id=?",Integer.class,op.id())==1)return;handler(op,c,lock);}
 private Map<String,Object> basicVehicle(long owner,long vehicle,boolean lock){db.one("SELECT id FROM vehicle WHERE id=? AND user_id=? AND is_deleted=0"+(lock?" FOR UPDATE":""),vehicle,owner);var v=db.one("SELECT b.name AS brand,s.name AS series,m.year,m.config_name FROM vehicle v LEFT JOIN model m ON m.id=v.model_id AND m.is_deleted=0 LEFT JOIN series s ON s.id=m.series_id AND s.is_deleted=0 LEFT JOIN brand b ON b.id=s.brand_id AND b.is_deleted=0 WHERE v.id=?",vehicle);var out=new LinkedHashMap<String,Object>();for(String k:List.of("brand","series","year","config_name"))out.put(k,v.get(k));return out;}
 private Map<String,Object> admit(VehicleOwner a,long vehicle,JsonNode b){
  service.guard();db.jdbc.queryForList("SELECT id FROM diagnosis_service_policy WHERE status='PUBLISHED' FOR UPDATE");
  db.jdbc.queryForList("SELECT id FROM operator_account WHERE status='ACTIVE' AND can_diagnose=1 ORDER BY id FOR UPDATE");
  db.jdbc.queryForList("SELECT id FROM invite_diagnosis_policy WHERE status='PUBLISHED' FOR UPDATE");
  db.jdbc.queryForList("SELECT r.user_id FROM invite_registration r JOIN `user` u ON u.id=r.user_id WHERE r.source_type='user' AND r.source_id=? AND r.attribution_result='ATTRIBUTED' AND r.identity_source='VERIFIED_WECHAT' AND r.qualification_status='QUALIFIED' AND u.status=1 AND u.is_deleted=0 ORDER BY r.user_id FOR UPDATE",a.id());
  basicVehicle(a.id(),vehicle,true);var available=DiagnosisServicePolicies.availability(db,true);var policy=(Map<?,?>)available.get("policy");if(!Boolean.TRUE.equals(available.get("accepting"))||policy==null||((Number)policy.get("id")).longValue()!=b.path("policy_id").asLong()||((Number)policy.get("revision")).longValue()!=b.path("policy_revision").asLong())throw DiagnosisServicePolicies.conflict();var proof=eligibility.eligibility(a.id(),true);
  var now=db.now();if(!"ELIGIBLE".equals(proof.get("state"))||!java.time.Instant.parse(proof.get("usable_until").toString()).isAfter(now)||!proof.get("month").equals(now.atZone(java.time.ZoneId.of("Asia/Shanghai")).toString().substring(0,7))||!java.time.Instant.parse(policy.get("valid_to").toString()).isAfter(now))throw DiagnosisServicePolicies.conflict();
  proof.put("service_available",true);return Map.of("eligibility",proof,"service",policy,"checked_at",now.toString());
 }
 public Map<String,Object> context(VehicleOwner a){return db.reads.execute(tx->{db.owner(a,false);var proof=eligibility.eligibility(a.id());var available=DiagnosisServicePolicies.availability(db);proof.put("service_available","ELIGIBLE".equals(proof.get("state"))&&Boolean.TRUE.equals(available.get("accepting")));return Map.of("service",available,"eligibility",proof);});}
 private String hash(JsonNode b){var sorted=new TreeMap<String,Object>();b.fields().forEachRemaining(e->sorted.put(e.getKey(),e.getValue()));return AuthTokens.sha256(db.json(sorted));}
 private Map<String,Object> summary(Map<String,Object> c,boolean manage){var out=new LinkedHashMap<String,Object>();out.put("case_id",c.get("id"));for(String k:List.of("revision","status"))out.put(k,c.get(k));for(String k:List.of("created_at","updated_at"))out.put(k,iso(c.get(k)));if(manage)out.put("assigned_operator_id",c.get("assigned_operator_id"));return out;}
 private Map<String,Object> receipt(long id,long revision,String status){return Map.of("case_id",id,"revision",revision,"status",status);}
 private void event(long id,long revision,String kind){db.jdbc.update("INSERT INTO diagnosis_case_event(case_id,case_revision,kind,occurred_at) VALUES(?,?,?,?)",id,revision,kind,time(db.now()));DiagnosisNotifications.enqueue(db,id,revision,kind);}
 private void message(long id,long revision,String sender,long senderId,String body,Object proof){db.jdbc.update("INSERT INTO diagnosis_message(case_id,case_revision,sender_type,sender_id,body,admission_snapshot,created_at) VALUES(?,?,?,?,?,?,?)",id,revision,sender,senderId,body,proof==null?null:db.json(proof),time(db.now()));}
 public JsonNode create(VehicleOwner a,String key,JsonNode b){String canonical=com.autocare.platform.common.write.WriteIntegrityService.normalizeKey(key),hash=hash(b);return db.writes.execute(new Actor("user",a.id()),"POST","/api/owner/diagnosis/cases",key,b,()->db.owner(a,true),()->{
  var old=db.jdbc.queryForList("SELECT id,submission_hash FROM diagnosis_case WHERE owner_id=? AND submission_key=? FOR UPDATE",a.id(),canonical);if(!old.isEmpty()){if(!hash.equals(old.get(0).get("submission_hash")))throw ReservationInput.bad();long id=number(old.get(0),"id");var r=receipt(id,1,"WAITING");return new Change("DIAGNOSIS_CREATE","diagnosis_case",id,r,r,r,false);}
  long vehicle=b.path("vehicle_id").asLong();var proof=admit(a,vehicle,b);long id=db.insert("INSERT INTO diagnosis_case(owner_id,vehicle_id,vehicle_snapshot,submission_key,submission_hash,admission_snapshot,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)",a.id(),vehicle,db.json(basicVehicle(a.id(),vehicle,false)),canonical,hash,db.json(proof),time(db.now()),time(db.now()));message(id,1,"OWNER",a.id(),b.path("message").asText(),proof);event(id,1,"CREATED");var r=receipt(id,1,"WAITING");return new Change("DIAGNOSIS_CREATE","diagnosis_case",id,Map.of(),r,r);
 });}
 public Map<String,Object> list(Object a,boolean queue,int page){return db.reads.execute(tx->{String where;Object id;if(a instanceof VehicleOwner u){db.owner(u,false);where="owner_id=?";id=u.id();}else{var op=(OperatorActor)a;service.operators.authorize(op,queue?OperatorIdentity.Permission.DIAGNOSE_MANAGE:OperatorIdentity.Permission.DIAGNOSE,false);where=queue?"1=?":"assigned_operator_id=?";id=queue?1:op.id();}long total=db.jdbc.queryForObject("SELECT COUNT(*) FROM diagnosis_case WHERE "+where,Long.class,id);return page(db.jdbc.queryForList("SELECT id,revision,status,created_at,updated_at,assigned_operator_id FROM diagnosis_case WHERE "+where+" ORDER BY id DESC LIMIT 20 OFFSET ?",id,(page-1)*20L).stream().map(c->summary(c,queue)).toList(),total,page,20);});}
 public Map<String,Object> detail(Object a,long id,int page){return db.reads.execute(tx->{scope(a,id,false,false);var c=row(id,false);long total=db.jdbc.queryForObject("SELECT COUNT(*) FROM diagnosis_message WHERE case_id=?",Long.class,id);var rows=db.jdbc.queryForList("SELECT id,sender_type,body,created_at FROM diagnosis_message WHERE case_id=? ORDER BY id LIMIT 20 OFFSET ?",id,(page-1)*20L);var items=new ArrayList<Map<String,Object>>();for(var r:rows)items.add(Map.of("message_id",r.get("id"),"sender",r.get("sender_type"),"body",r.get("body"),"created_at",iso(r.get("created_at"))));return Map.of("case",summary(c,false),"vehicle",db.parse(c.get("vehicle_snapshot")),"messages",page(items,total,page,20));});}
 public JsonNode assign(OperatorActor a,long id,String key,JsonNode b){long target=b.path("operator_id").asLong();return db.writes.execute(new Actor("operator_account",a.id()),"PUT","/api/admin/diagnosis/cases/"+id+"/assignment",key,b,()->{service.manage(a,false);service.guard();db.jdbc.queryForList("SELECT id FROM operator_account WHERE id IN (?,?) ORDER BY id FOR UPDATE",a.id(),target);service.manage(a,true);db.one("SELECT id FROM operator_account WHERE id=? AND status='ACTIVE' AND can_diagnose=1 FOR UPDATE",target);row(id,true);},()->{var c=row(id,true);check(c,b);var before=summary(c,true);long rev=number(c,"revision")+1;db.jdbc.update("UPDATE diagnosis_case SET assigned_operator_id=?,status='PROCESSING',revision=?,updated_at=? WHERE id=?",target,rev,time(db.now()),id);event(id,rev,"ASSIGNED");var after=receipt(id,rev,"PROCESSING");return new Change("DIAGNOSIS_ASSIGN","diagnosis_case",id,before,after,after);});}
 private void check(Map<String,Object> c,JsonNode b){if("CLOSED".equals(c.get("status"))||number(c,"revision")!=b.path("expected_revision").asLong())throw DiagnosisServicePolicies.conflict();}
 public JsonNode write(Object a,long id,String action,String key,JsonNode b){boolean own=a instanceof VehicleOwner;var actor=own?new Actor("user",((VehicleOwner)a).id()):new Actor("operator_account",((OperatorActor)a).id());return db.writes.execute(actor,"POST","/api/"+(own?"owner":"admin")+"/diagnosis/cases/"+id+"/"+action,key,b,()->{scope(a,id,false,action.equals("close"));if(own)db.owner((VehicleOwner)a,true);service.guard();scope(a,id,true,action.equals("close"));},()->{
  var c=row(id,true);check(c,b);var before=summary(c,false);long rev=number(c,"revision")+1;String status,kind;
  if(action.equals("close")){status="CLOSED";kind="CLOSED";}else if(own){var proof=admit((VehicleOwner)a,number(c,"vehicle_id"),b);boolean valid=c.get("assigned_operator_id")!=null&&!db.jdbc.queryForList("SELECT id FROM operator_account WHERE id=? AND status='ACTIVE' AND can_diagnose=1 FOR UPDATE",c.get("assigned_operator_id")).isEmpty();status=valid?"PROCESSING":"WAITING";if(!valid)db.jdbc.update("UPDATE diagnosis_case SET assigned_operator_id=NULL WHERE id=?",id);message(id,rev,"OWNER",actor.id(),b.path("message").asText(),proof);kind="MESSAGE";}else{if(!"PROCESSING".equals(c.get("status")))throw DiagnosisServicePolicies.conflict();status="REPLIED";kind="REPLIED";message(id,rev,"OPERATOR",actor.id(),b.path("message").asText(),null);}
  db.jdbc.update("UPDATE diagnosis_case SET revision=?,status=?,updated_at=?,closed_at=? WHERE id=?",rev,status,time(db.now()),status.equals("CLOSED")?time(db.now()):null,id);event(id,rev,kind);var after=receipt(id,rev,status);return new Change("DIAGNOSIS_"+kind,"diagnosis_case",id,before,after,after);
 });}
}
